Storage Allocator (K&R Chapter 8):
#include <unistd.h>

typedef struct header {  // block header
    size_t size;
    struct header *next;
} Header;

// free list (circular)
static Header base = {0, &base};
static Header *freep = &base;  // last found block

void *kalloc(size_t n) {
    // round up to header units + header itself
    size_t nunits = (n + sizeof(Header) - 1) / sizeof(Header) + 1;
    Header *prev = freep;

    for (Header *p = prev->next; ; prev = p, p = p->next) {
        if (p->size >= nunits) {  // enough space?
            if (p->size == nunits)
                prev->next = p->next;  // exact fit
            else {
                p->size -= nunits;  // split block
                p += p->size;
                p->size = nunits;
            }
            freep = prev;
            return (void *)(p + 1);  // past header
        }
        if (p == freep) return NULL;  // wrapped: no space
    }
}

