void safe_copy(const char *src, char *dst, size_t dst_size) {
    assert(src != NULL);   // crash in debug instead of silent
    assert(dst != NULL);

    size_t len = strlen(src);
    if (len >= dst_size) {  // check before copy
        fprintf(stderr, "Buffer too small: %zu >= %zu\n", len, dst_size);
        return;
    }
    memcpy(dst, src, len + 1);  // include null terminator
}

int divide(int a, int b, int *result) {
    if (b == 0) return -1;   // guard against division by zero
    if (result == NULL) return -1;  // guard output pointer
    *result = a / b;
    return 0;  // success
}

