Custom Allocators (Arena):
#include <stdlib.h>
#include <stdalign.h>
#include <assert.h>

typedef struct {
    char *start;
    char *ptr;
    size_t remaining;
} Arena;

void arena_init(Arena *a, size_t size) {
    a->start = malloc(size);
    a->ptr = a->start;
    a->remaining = size;
}

void *arena_alloc(Arena *a, size_t size, size_t align) {
    // Align pointer
    uintptr_t p = (uintptr_t)a->ptr;
    uintptr_t aligned = (p + align - 1) & ~(align - 1);
    size_t padding = aligned - p;
    if (padding + size > a->remaining) return NULL;
    a->ptr = (char*)(aligned + size);
    a->remaining -= padding + size;
    return (void*)aligned;
}

void arena_reset(Arena *a) {
    a->ptr = a->start;
    a->remaining = a->remaining + (a->ptr - a->start);
}

void arena_destroy(Arena *a) {
    free(a->start);
    a->start = NULL;
    a->ptr = NULL;
    a->remaining = 0;
}

